package com.pranit.helpdesk.service;
import com.pranit.helpdesk.dto.*; import com.pranit.helpdesk.entity.User; import com.pranit.helpdesk.model.Role; import com.pranit.helpdesk.repository.UserRepository; import com.pranit.helpdesk.security.JwtService; import org.springframework.security.authentication.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AuthService{private final UserRepository users;private final PasswordEncoder encoder;private final AuthenticationManager auth;private final JwtService jwt;public AuthService(UserRepository u,PasswordEncoder e,AuthenticationManager a,JwtService j){users=u;encoder=e;auth=a;jwt=j;}public AuthResponse register(RegisterRequest r){if(users.findByUsername(r.username()).isPresent())throw new IllegalArgumentException("Username already exists");if(users.findByEmail(r.email()).isPresent())throw new IllegalArgumentException("Email already exists");User u=new User();u.setUsername(r.username());u.setEmail(r.email());u.setPassword(encoder.encode(r.password()));u.setRole(Role.USER);users.save(u);return new AuthResponse(jwt.generate(u.getUsername(),u.getRole().name()),u.getUsername(),u.getRole().name());}public AuthResponse login(LoginRequest r){auth.authenticate(new UsernamePasswordAuthenticationToken(r.username(),r.password()));User u=users.findByUsername(r.username()).orElseThrow();return new AuthResponse(jwt.generate(u.getUsername(),u.getRole().name()),u.getUsername(),u.getRole().name());}}
